import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:respondify/models/event.dart';
import 'package:respondify/models/intention.dart';

class EventIntentionResponse extends StatefulWidget {
  final Event event;
  final Intention intention;

  const EventIntentionResponse({
    Key? key,
    required this.event,
    required this.intention,
  }) : super(key: key);

  @override
  State<EventIntentionResponse> createState() =>
      _EventIntentionResponseState(event: event, intention: intention);
}

class _EventIntentionResponseState extends State<EventIntentionResponse> {
  final Event event;
  final Intention intention;

  late String response;

  _EventIntentionResponseState({
    required this.event,
    required this.intention,
  });

  @override
  void initState() {
    super.initState();
    _predictResponse();
  }

  void _predictResponse() {
    String eventSubject = event.actionSubject.toLowerCase();

    switch (eventSubject) {
      case 'step on':
        response = 'to release tension and reduce frustration';
        break;
      case 'hold':
        response = 'to maintain order and organization';
        break;
      case 'hear':
        response =
            'to attend to and potentially respond to an emergency or important message';
        break;
      default:
        response = 'to ${intention.verb}';
    }
  }

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Text(
        response,
        style: TextStyle(
          fontSize: 24,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }
}

