  actionObject: 'PersonX ___',
);

Intention intentionSample = Intention(
  verb: 'give outlet to anger',
  motivation: 'to let out pent-up emotions',
);

EventIntentionResponse(responseEvent: eventSample, responseIntention: intentionSample);

