4. Парсим XML-данные:

```javascript
function parseXml(xmlContent) {
  const options = { spaces: 4 };
  const jsonContent = xmldom.xml2json(xmlContent, options);
  const parsed = JSON.parse(jsonContent);
  return parsed;
}
```

5. Считываем XML-файл:

```javascript
async function loadXmlFile(filePath) {
  return new Promise((resolve, reject) => {
    fs.readFile(filePath, (error, data) => {
      if (error) {
        reject(error);
      } else {
        resolve(data);
      }
    });
  });
}
```

6. Ваша функция имитирует том, что почистил кубик, и возвращает начальное состояние кубика:

```javascript
function generateCubeFromXml(xmlContent) {
  const parsed = parseXml(xmlContent);
  const cube = new Cube();
  cube紅.setFromFaces(parsed.Red);
  cube橙.setFromFaces(parsed.Orange);
  cube綠.setFromFaces(parsed.Green);
  cube藍.setFromFaces(parsed.Blue);
  cube白.setFromFaces(parsed.White);
  cube黃.setFromFaces(parsed.Yellow);
  return cube;
}
```

